<script setup lang="ts">
import {computed,nextTick,onMounted,ref,watch} from 'vue'
import {localDateTime,reviewDraft} from '../lib/form-values.mjs'
import {usePagedItems} from '../lib/paged-items'
import ResultPager from './ResultPager.vue'
import {studentApi,type Review} from '../api/student-capabilities'
import type {ReviewEdit} from '../api/backend-types'
import {backendDemo} from '../lib/backend-demo'
import {backendClient} from '../api/backend-client'
import {actionRows} from '../lib/action-insights.mjs'
import DetailPopover from './DetailPopover.vue'
const props=defineProps<{taskId?:string}>()
const emit=defineEmits<{loaded:[items:Review[]]}>()
const tasks=computed(()=>actionRows(backendDemo.state.liveAction)),selectedId=ref(''),reason=ref(''),note=ref(''),result=ref<ReviewEdit['result']>('continue'),adjustedText=ref(''),adjustedDate=ref(''),editing=ref(''),busy=ref(false),error=ref(''),status=ref(''),items=ref<Review[]>([]),reasons=ref<Record<string,number>>({})
const {page,paged}=usePagedItems(computed(()=>items.value),5)
const loading=ref(false),form=ref<HTMLFormElement|null>(null),opened=ref('')
const selected=computed(()=>tasks.value.find(t=>t.task_id===selectedId.value))
watch(selectedId,()=>{const draft=reviewDraft(selected.value);editing.value='';reason.value='';note.value='';adjustedText.value=draft.text;adjustedDate.value=draft.due;result.value='continue';status.value='';error.value=''})
watch(()=>props.taskId,id=>{if(id)selectedId.value=id},{immediate:true})
async function load(){loading.value=true;error.value='';try{const data=await studentApi.reviews();items.value=data.items;reasons.value=data.reasons;emit('loaded',data.items)}catch(e){error.value=(e as Error).message}finally{loading.value=false}}
async function save(){if(!selected.value||busy.value)return;busy.value=true;error.value='';status.value='';try{const t=selected.value,phase=backendDemo.state.liveAction?.phases?.find(p=>(p.tasks??[]).some(row=>row.task_id===t.task_id));const item=await studentApi.saveReview({task_id:t.task_id,reason:reason.value,note:note.value,result:result.value,adjustment:result.value==='adjust'?{text:adjustedText.value,phase_id:phase?.id??'',status:t.status??'pending',progress:t.progress??0,waiting_reason:t.waiting_reason??'',due_date:adjustedDate.value?new Date(adjustedDate.value).toISOString():t.due_date,scheduled_at:t.scheduled_at,estimated_minutes:t.estimated_minutes,parent_task_id:t.parent_task_id}:null},editing.value||undefined);editing.value=item.id;await load();status.value=error.value?'复盘已保存，列表暂未刷新。':result.value==='continue'?'复盘已保存。':'复盘已保存，点击「应用到计划」后才会修改任务。'}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function apply(item:Review){if(busy.value)return;busy.value=true;error.value='';status.value='';try{await studentApi.applyReview(item.id);backendDemo.setAction(await backendClient.action());await load();status.value=error.value?'计划已更新，复盘列表暂未刷新。':'复盘结论已应用到阶段计划。'}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function edit(item:Review){selectedId.value=item.task_id;await nextTick();editing.value=item.id;reason.value=item.reason;note.value=item.note??'';result.value=item.result;adjustedText.value=item.adjustment?.text??item.task_text;const due=item.adjustment?.due_date;adjustedDate.value=localDateTime(due);opened.value='';await nextTick();form.value?.querySelector<HTMLElement>('select')?.focus()}
onMounted(load)
</script>
<template><section class="structured-review ws-two-columns"><section class="ws-paper"><h2>选择一件事复盘</h2><form ref="form" @submit.prevent="save"><fieldset :disabled="busy"><label class="ws-field">关联任务<select v-model="selectedId" required><option value="">选择一项任务</option><option v-for="t in tasks" :key="t.task_id" :value="t.task_id">{{t.done?'已完成':'未完成'}} · {{t.text}}</option></select></label><template v-if="selected"><label class="ws-field">主要原因<select v-model="reason" required><option value="">选择原因</option><option v-for="r in ['达到预期','任务太大','方法不对','时间不足','等待他人','方向要重估','其他']" :key="r">{{r}}</option></select></label><label class="ws-field">实际情况<textarea v-model="note" rows="4" maxlength="3000"/></label><label class="ws-field">下一步结论<select v-model="result"><option value="continue">保留记录，继续执行</option><option value="adjust">调整任务</option><option value="complete">确认完成</option></select></label><template v-if="result==='adjust'"><label class="ws-field">调整后的任务<input v-model="adjustedText" required/></label><label class="ws-field">调整后的截止时间<input v-model="adjustedDate" type="datetime-local"/></label></template><button class="btn btn--primary" :disabled="busy">{{busy?'正在保存…':editing?'保存修订':'保存复盘'}}</button></template></fieldset></form><p v-if="error" role="alert">{{error}}</p><p v-if="status" role="status">{{status}}</p></section><aside class="review-side"><h2>归因统计</h2><dl><template v-for="(count,label) in reasons" :key="label"><dt>{{label}}</dt><dd>{{count}} 次</dd></template></dl><p v-if="!items.length" class="ws-muted">保存复盘后在这里统计。</p><h2>已保存复盘</h2><p v-if="loading" class="ws-muted" role="status">正在读取复盘…</p><button v-if="error" class="ws-text-button" :disabled="busy||loading" @click="load">重新读取复盘</button><article v-for="item in paged" :key="item.id" class="review-entry"><h3>{{item.task_text}}</h3><p>{{item.reason}} · {{new Date(item.updated_at).toLocaleDateString()}}</p><DetailPopover :model-value="opened===item.id" @update:model-value="opened=$event?item.id:''" :label="item.task_text+'：查看复盘与修订'" :title="item.task_text" side="right"><template #trigger>查看复盘与修订</template><p>{{item.note}}</p><p>{{item.applied_at?'已应用于 '+new Date(item.applied_at).toLocaleString():item.result==='continue'?'仅保留记录，无需应用':'尚未应用任务调整'}}</p><p v-for="(v,i) in item.history" :key="i">修订前：{{v.reason}} · {{v.note}}</p><button class="btn" :disabled="busy" @click="edit(item)">修订复盘</button><button v-if="item.result!=='continue'&&!item.applied_at" class="btn" :disabled="busy" @click="apply(item)">应用到计划</button></DetailPopover></article><ResultPager v-model:page="page" :total="items.length" :size="5" label="已保存复盘"/></aside></section></template>
<style scoped>form fieldset{display:grid;gap:14px;min-width:0;border:0;padding:0;margin:0}form .ws-field{margin-top:0}.review-entry h3,.review-entry p{overflow-wrap:anywhere}form{display:grid;gap:14px;margin-top:16px}.review-entry{padding:16px 0;border-bottom:1px solid var(--c-border)}dl{display:grid;grid-template-columns:1fr auto;gap:8px;margin:16px 0}.review-entry h3{font-size:var(--fs-14)}</style>
